import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const MAX_INPUT = 64 * 1024;
const MAX_OUTPUT = 1024 * 1024;
const MAX_RSS_KB = 96 * 1024;
const DEADLINE_MS = 200;
const WORKER = fileURLToPath(new URL('./parser-worker.mjs', import.meta.url));
const unreadable = () => ({ status: 422, body: { kind: 'unreadable', kept: true } });

let active = 0;
const waiting = [];
function acquire() {
  if (active < 1) { active++; return Promise.resolve(true); }
  if (waiting.length >= 2) return Promise.resolve(false);
  return new Promise(resolve => waiting.push(resolve));
}
function release() {
  const next = waiting.shift();
  if (next) next(true); else active--;
}

function runParser(buffer) {
  return new Promise(resolve => {
    let child;
    try {
      // Empty env prevents inherited secrets from reaching the parser. The worker has
      // no library-provided limits, so the parent supervises its wall time and RSS.
      child = spawn(process.execPath, [WORKER], { env: {}, stdio: ['pipe', 'pipe', 'ignore'] });
    } catch { resolve(null); return; }
    let output = Buffer.alloc(0), settled = false, overLimit = false;
    const finish = value => {
      if (settled) return;
      settled = true; clearTimeout(deadline); clearInterval(memoryCheck);
      resolve(value);
    };
    child.on('error', () => finish(null));
    child.stdout.on('data', chunk => {
      output = Buffer.concat([output, chunk]);
      if (output.length > MAX_OUTPUT) { overLimit = true; child.kill('SIGKILL'); }
    });
    child.on('close', code => {
      if (code !== 0 || overLimit) return finish(null);
      try { finish(JSON.parse(output.toString('utf8'))); } catch { finish(null); }
    });
    const deadline = setTimeout(() => { child.kill('SIGKILL'); finish(null); }, DEADLINE_MS);
    const memoryCheck = setInterval(() => {
      // `ps` reads the child RSS on macOS and Linux; kill promptly above 96 MiB.
      const probe = spawn('/bin/sh', ['-c', `ps -o rss= -p ${child.pid}`], { env: {}, stdio: ['ignore', 'pipe', 'ignore'] });
      let value = '';
      probe.stdout.on('data', data => value += data.toString());
      probe.on('close', () => {
        if (Number.parseInt(value, 10) > MAX_RSS_KB) { overLimit = true; child.kill('SIGKILL'); }
      });
    }, 10);
    child.stdin.end(buffer);
  });
}

export async function upload(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length > MAX_INPUT) return unreadable();
  if (!await acquire()) return { status: 503, body: { kind: 'busy', retryable: true } };
  try {
    const result = await runParser(buffer);
    if (!result || typeof result.xml !== 'string' || Buffer.byteLength(result.xml) > MAX_OUTPUT) return unreadable();
    const title = /<title>(.*?)<\/title>/s.exec(result.xml)?.[1];
    if (!title) return unreadable();
    return { status: 200, body: { kind: 'proposal', title } };
  } catch { return unreadable(); }
  finally { release(); }
}

